package com.primehr.succession.domain;

import com.primehr.rsp.domain.RspAuditedEntity;
import com.primehr.shared.exception.IllegalLifecycleTransitionException;
import jakarta.persistence.*;
import java.time.*;
import java.util.Locale;

@Entity @Table(name="succession_cycle",uniqueConstraints=@UniqueConstraint(name="uk_succession_cycle_code",columnNames={"agency_id","normalized_code"}))
public class SuccessionCycle extends RspAuditedEntity {
 public enum Status{DRAFT,OPEN,CLOSED,CANCELLED}
 @Column(nullable=false,length=80) private String code; @Column(name="normalized_code",nullable=false,length=80) private String normalizedCode;
 @Column(nullable=false,length=200) private String title; @Column(length=2000) private String description;
 @Column(name="policy_version_id",nullable=false,length=36) private String policyVersionId; @Column(name="policy_definition_version",nullable=false) private int policyDefinitionVersion; @Column(name="policy_fingerprint",nullable=false,length=120) private String policyFingerprint;
 @Column(name="charter_version_id",nullable=false,length=36) private String charterVersionId; @Column(name="nomination_opens_on",nullable=false) private LocalDate nominationOpensOn; @Column(name="nomination_closes_on",nullable=false) private LocalDate nominationClosesOn; @Column(name="eligibility_due_on",nullable=false) private LocalDate eligibilityDueOn;
 @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private Status status; @Column(name="opened_by",length=100) private String openedBy; @Column(name="opened_at") private Instant openedAt; @Column(name="closed_by",length=100) private String closedBy; @Column(name="closed_at") private Instant closedAt; @Column(name="transition_reason",length=2000) private String transitionReason;
 protected SuccessionCycle(){}
 public SuccessionCycle(String agency,String code,String title,String description,String policyId,int policyVersion,String policyFingerprint,String charterId,LocalDate opens,LocalDate closes,LocalDate due){super(agency);this.code=requiredText(code,"code");normalizedCode=this.code.toUpperCase(Locale.ROOT);status=Status.DRAFT;apply(title,description,policyId,policyVersion,policyFingerprint,charterId,opens,closes,due);}
 public void update(String title,String description,String policyId,int policyVersion,String policyFingerprint,String charterId,LocalDate opens,LocalDate closes,LocalDate due){draft();apply(title,description,policyId,policyVersion,policyFingerprint,charterId,opens,closes,due);}
 private void apply(String title,String description,String policyId,int policyVersion,String fingerprint,String charterId,LocalDate opens,LocalDate closes,LocalDate due){if(opens==null||closes==null||due==null||closes.isBefore(opens)||due.isBefore(closes))throw new IllegalArgumentException("Succession cycle dates must be chronological");if(policyVersion<1)throw new IllegalArgumentException("policyDefinitionVersion must be positive");this.title=requiredText(title,"title");this.description=optionalText(description);policyVersionId=requiredText(policyId,"policyVersionId");policyDefinitionVersion=policyVersion;policyFingerprint=requiredText(fingerprint,"policyFingerprint");charterVersionId=requiredText(charterId,"charterVersionId");nominationOpensOn=opens;nominationClosesOn=closes;eligibilityDueOn=due;}
 public void open(String actor,String reason,Instant at){draft();status=Status.OPEN;openedBy=requiredText(actor,"actor");openedAt=at;transitionReason=requiredText(reason,"reason");}
 public void close(String actor,String reason,Instant at){if(status!=Status.OPEN)throw new IllegalLifecycleTransitionException("Only an open succession cycle may be closed");status=Status.CLOSED;closedBy=requiredText(actor,"actor");closedAt=at;transitionReason=requiredText(reason,"reason");}
 public void cancel(String actor,String reason,Instant at){if(status!=Status.DRAFT&&status!=Status.OPEN)throw new IllegalLifecycleTransitionException("Only draft or open succession cycles may be cancelled");status=Status.CANCELLED;closedBy=requiredText(actor,"actor");closedAt=at;transitionReason=requiredText(reason,"reason");}
 public boolean accepts(LocalDate on){return status==Status.OPEN&&!on.isBefore(nominationOpensOn)&&!on.isAfter(nominationClosesOn);} private void draft(){if(status!=Status.DRAFT)throw new IllegalLifecycleTransitionException("Only a draft succession cycle may be changed");}
 public String getCode(){return code;} public String getTitle(){return title;} public String getDescription(){return description;} public String getPolicyVersionId(){return policyVersionId;} public int getPolicyDefinitionVersion(){return policyDefinitionVersion;} public String getPolicyFingerprint(){return policyFingerprint;} public String getCharterVersionId(){return charterVersionId;} public LocalDate getNominationOpensOn(){return nominationOpensOn;} public LocalDate getNominationClosesOn(){return nominationClosesOn;} public LocalDate getEligibilityDueOn(){return eligibilityDueOn;} public Status getStatus(){return status;} public String getOpenedBy(){return openedBy;} public Instant getOpenedAt(){return openedAt;} public String getClosedBy(){return closedBy;} public Instant getClosedAt(){return closedAt;} public String getTransitionReason(){return transitionReason;}
}
